/**
 * useTetris.js
 * 把 reducer 状态机封装成一个 Hook，负责“不纯”的部分：
 *  - 重力定时器（按等级调整下落间隔）
 *  - 全局键盘监听（左右移动 / 旋转 / 软降 / 硬降 / 暂停 / 重开）
 * 并对外暴露 state 与一组语义化操作。
 */

import { useCallback, useEffect, useMemo, useReducer } from 'react';
import { Action, Status, createInitialState, tetrisReducer } from './tetrisReducer';

/** 等级 1 时的下落间隔（毫秒） */
const BASE_INTERVAL = 800;
/** 每升一级减少的间隔 */
const LEVEL_STEP = 70;
/** 最小间隔，避免过快无法操作 */
const MIN_INTERVAL = 90;

/** 根据等级计算重力下落间隔 */
export function getDropInterval(level) {
  return Math.max(MIN_INTERVAL, BASE_INTERVAL - (level - 1) * LEVEL_STEP);
}

/** 这些按键的默认行为需要被拦截（避免页面滚动） */
const PREVENT_KEYS = new Set([
  'ArrowLeft',
  'ArrowRight',
  'ArrowUp',
  'ArrowDown',
  ' ',
  'Spacebar',
]);

export function useTetris() {
  const [state, dispatch] = useReducer(
    tetrisReducer,
    undefined,
    () => createInitialState(false)
  );

  const dropInterval = useMemo(() => getDropInterval(state.level), [state.level]);

  // ---- 重力：仅在 playing 时运行，等级变化即时生效 ----
  useEffect(() => {
    if (state.status !== Status.PLAYING) return undefined;
    const timer = window.setInterval(() => {
      dispatch({ type: Action.TICK });
    }, dropInterval);
    return () => window.clearInterval(timer);
  }, [state.status, dropInterval]);

  // ---- 语义化操作 ----
  const start = useCallback(() => dispatch({ type: Action.START }), []);
  const reset = useCallback(() => dispatch({ type: Action.RESET }), []);
  const togglePause = useCallback(() => dispatch({ type: Action.TOGGLE_PAUSE }), []);
  const moveLeft = useCallback(() => dispatch({ type: Action.MOVE, payload: { dx: -1 } }), []);
  const moveRight = useCallback(() => dispatch({ type: Action.MOVE, payload: { dx: 1 } }), []);
  const rotateCW = useCallback(() => dispatch({ type: Action.ROTATE, payload: { dir: 1 } }), []);
  const rotateCCW = useCallback(() => dispatch({ type: Action.ROTATE, payload: { dir: -1 } }), []);
  const softDrop = useCallback(() => dispatch({ type: Action.SOFT_DROP }), []);
  const hardDrop = useCallback(() => dispatch({ type: Action.HARD_DROP }), []);

  // ---- 键盘控制 ----
  useEffect(() => {
    const handleKeyDown = (event) => {
      if (PREVENT_KEYS.has(event.key)) event.preventDefault();
      if (event.repeat && (event.key === 'p' || event.key === 'P')) return;

      const isStartKey = event.key === 'Enter' || event.key === ' ' || event.key === 'Spacebar';

      // 未开始 / 已结束时，直接按回车或空格即可开始
      if (isStartKey && (state.status === Status.READY || state.status === Status.OVER)) {
        start();
        return;
      }
      if (event.key === 'Enter') {
        reset();
        return;
      }

      switch (event.key) {
        case 'ArrowLeft':
          moveLeft();
          break;
        case 'ArrowRight':
          moveRight();
          break;
        case 'ArrowDown':
          softDrop();
          break;
        case 'ArrowUp':
        case 'x':
        case 'X':
          rotateCW();
          break;
        case 'z':
        case 'Z':
          rotateCCW();
          break;
        case ' ':
        case 'Spacebar':
          hardDrop();
          break;
        case 'p':
        case 'P':
        case 'Escape':
          togglePause();
          break;
        default:
          break;
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [
    state.status,
    start,
    reset,
    togglePause,
    moveLeft,
    moveRight,
    rotateCW,
    rotateCCW,
    softDrop,
    hardDrop,
  ]);

  return {
    state,
    dropInterval,
    actions: {
      start,
      reset,
      togglePause,
      moveLeft,
      moveRight,
      rotateCW,
      rotateCCW,
      softDrop,
      hardDrop,
    },
  };
}

export { Action, Status };
export default useTetris;

