import { useMemo } from 'react';
import useTetris from './game/useTetris';
import { Status } from './game/tetrisReducer';
import { COLS, ROWS, getDropY } from './game/tetrominoes';

/** 把棋盘 + 当前方块 + 幽灵方块合成用于渲染的网格 */
function buildGrid(board, piece) {
  const grid = board.map((row) => row.map((color) => (color ? { color } : null)));
  if (!piece) return grid;
  const ghostY = getDropY(board, piece);
  const stamp = (baseY, isGhost) => {
    for (let r = 0; r < piece.matrix.length; r += 1) {
      for (let c = 0; c < piece.matrix[r].length; c += 1) {
        if (!piece.matrix[r][c]) continue;
        const y = baseY + r;
        const x = piece.x + c;
        if (y < 0 || y >= ROWS || x < 0 || x >= COLS) continue;
        if (isGhost && grid[y][x]) continue;
        grid[y][x] = { color: piece.color, ghost: isGhost };
      }
    }
  };
  stamp(ghostY, true);
  stamp(piece.y, false);
  return grid;
}

function MiniPiece({ type, matrix, color }) {
  if (!matrix) return null;
  return (
    <div className="mini">
      {matrix.map((row, r) => (
        <div className="mini-row" key={r}>
          {row.map((v, c) => (
            <span key={c} className="mini-cell" style={v ? { background: color } : undefined} />
          ))}
        </div>
      ))}
    </div>
  );
}

export default function App() {
  const { state, actions } = useTetris();
  const { board, current, queue, score, lines, level, status } = state;

  const grid = useMemo(() => buildGrid(board, current), [board, current]);

  const nextType = queue[0];
  const nextMatrix = nextType ? current && nextType === current.type ? null : undefined : undefined;

  return (
    <div className="app">
      <header className="header">
        <h1>俄罗斯方块</h1>
        <p className="hint">
          ← → 移动 ｜ ↑ / X 顺时针 ｜ Z 逆时针 ｜ ↓ 软降 ｜ 空格 硬降 ｜ P / Esc 暂停 ｜ Enter 重开
        </p>
      </header>

      <main className="layout">
        <div className="board-wrap">
